    /// <summary>
    /// Reads each window's dataset identity once, so the first frame already
    /// reports the real total count instead of an empty list. Reading it is a
    /// lock-free producer-side lookup; it never enters application model code.
    /// </summary>
    private void PrimeWindows(IAvnRustRangeSource? source)
    {
        if (source is null) return;
        if (source.GetRangeState(5, out var generation5, out var total5) >= 0)
            LogWindow.ResetTo(generation5, total5);
    }

    private void DisposeNestedAdapters()
    {
        TryDispose(_address);
        foreach (var item in Tasks) TryDispose(item);
        foreach (var item in TraceRows) TryDispose(item);
        foreach (var item in LogTree) TryDispose(item);
        TryDispose(LogWindow);
        foreach (var entry in SourceDetails) TryDispose(entry.Value);
        TryDispose(_saveResult);
    }

    private static void TryDispose(IDisposable? value)
    {
        try { value?.Dispose(); }
        catch { }
    }

    private int Apply(Action action) => Apply(() =>
    {
        action();
        return 0;
    });

    private int Apply(Func<int> action)
    {
        if (_batch.IsClosed) return 0;
        var hresult = 0;
        void ApplyIfAlive()
        {
            if (!_batch.IsClosed)
            {
                try { hresult = action(); }
                catch { hresult = unchecked((int)0x80004005); }
            }
        }
        try { _dispatch(ApplyIfAlive); }
        catch { return unchecked((int)0x80004005); }
        return hresult;
    }

    private static void Dispatch(Action action)
    {
        if (Dispatcher.UIThread.CheckAccess()) action();
        else Dispatcher.UIThread.Invoke(action);
    }

    private static void Check(int hresult)
    {
        if (hresult < 0) Marshal.ThrowExceptionForHR(hresult);
    }

    private void SetField<T>(ref T field, T value, [CallerMemberName] string? propertyName = null)
    {
        if (Equals(field, value)) return;
        field = value;
        PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(propertyName));
    }

    private void SetError(string propertyName, string? message)
    {
        if (RustVmBatchErrors.Set(_errors, propertyName, message))
            ErrorsChanged?.Invoke(this, new DataErrorsChangedEventArgs(propertyName));
    }

    public sealed class DelegateCommand(Action<object?> execute) : ICommand, IRustVmBatchCommand
    {
        private bool _canExecute = true;

        public DelegateCommand(Action execute) : this(_ => execute()) { }

        public event EventHandler? CanExecuteChanged;
        public bool CanExecute(object? parameter) => _canExecute;
        public void Execute(object? parameter) => execute(parameter);

        public void SetEnabled(bool value)
        {
            if (SetEnabledCore(value)) RaiseCanExecuteChanged();
        }

        public bool SetEnabledCore(bool enabled)
        {
            if (_canExecute == enabled) return false;
            _canExecute = enabled;
            return true;
        }

        public void RaiseCanExecuteChanged() => CanExecuteChanged?.Invoke(this, EventArgs.Empty);
    }
}
